void Solver::bump_var(int var, double coeff) {
    if (coeff == 0.0) return;

    double inc = var_inc * coeff;
    double newAct = activity[var] + inc;

    if (newAct > 1e100) {
        // Update activity before rescaling (as in original implementation)
        activity[var] = newAct;
        // Rescale all activities and the increment factor to avoid overflow
        const double scale = 1e-100;
        for (int i = 1; i <= vars; ++i) activity[i] *= scale;
        var_inc *= scale;
    } else {
        activity[var] = newAct;
    }

    // Keep the VSIDS heap consistent
    if (vsids.inHeap(var)) vsids.update(var);
}
